.single-color {
    display: none;
    visiblilty: hidden;
    width: 0;
    height: 0
}

.bottom .toggle-footer-logo {
    display: none
}

.meta {
    font-weight: 700;
    text-transform: uppercase;
    font-size: 1.4rem;
    line-height: 1.2
}

.meta .field {
    display: inline-block
}

.meta .field+.field:before {
    content: '';
    display: block;
    width: 3px;
    height: 3px;
    border: 2px solid #343434;
    background: #343434;
    border-radius: 100%;
    float: left;
    margin: .3em 1rem
}

.field__date {
    font-weight: 700;
    text-transform: uppercase;
    font-size: 1.4rem;
    line-height: 1.2
}

.field__subtitle {
    font-size: 2.8rem;
    font-weight: 700;
    line-height: 1.4;
    margin: 2.8rem auto
}

.group-card .field__subtitle {
    font-size: 1.6rem;
    font-weight: 400;
    line-height: 1.6
}

.node--experience.view-mode-full .field__subtitle,
.node--campaign.view-mode-full .field__subtitle {
    letter-spacing: -0.025em;
    padding: 4rem 2rem
}

@media (min-width:640px) {

    .node--experience.view-mode-full .field__subtitle,
    .node--campaign.view-mode-full .field__subtitle {
        padding: 0 4rem
    }
}

.node--experience.view-mode-full .bean-park-embed .field__subtitle,
.node--campaign.view-mode-full .bean-park-embed .field__subtitle {
    padding: 0
}

.field__body ul {
    list-style: none outside
}

.field__body ul li:before {
    content: "";
    display: inline-block;
    width: 2rem;
    height: .8rem;
    background: #343434;
    margin: -.2rem 1.5rem 0 -3rem;
    vertical-align: middle
}

.field__body ol {
    list-style: decimal outside
}

.field__body li ul,
.field__body li ol {
    margin-top: 2em
}

.view-mode-full .field__body ul,
.view-mode-full .field__body ol {
    margin-bottom: 2em
}

.view-mode-full .field__body ul li,
.view-mode-full .field__body ol li {
    margin: 0 5rem 1.5em
}

.view-mode-full .field__body ul>.column,
.view-mode-full .field__body ol>.column {
    padding: 0 2rem
}

.view-mode-full .field__body ul>.column li,
.view-mode-full .field__body ol>.column li {
    margin: 0 0 1.5em
}

.view-mode-full .field__body ul>.column li ol,
.view-mode-full .field__body ul>.column li ul,
.view-mode-full .field__body ol>.column li ol,
.view-mode-full .field__body ol>.column li ul {
    padding: 0 2rem
}

.view-mode-full .field__body ul.two-col,
.view-mode-full .field__body ol.two-col {
    width: initial;
    float: none;
    display: block;
    margin-bottom: 0
}

@media (min-width:960px) {

    .view-mode-full .field__body ul.two-col:after,
    .view-mode-full .field__body ol.two-col:after {
        content: "";
        display: table;
        clear: both
    }

    .view-mode-full .field__body ul.two-col>li,
    .view-mode-full .field__body ol.two-col>li {
        width: 40%;
        float: left;
        margin-right: 0;
        margin-left: 2rem;
        padding: 0 2rem 0 0;
        box-sizing: content-box
    }

    .view-mode-full .field__body ul.two-col>li:nth-child(2n+1),
    .view-mode-full .field__body ol.two-col>li:nth-child(2n+1) {
        clear: both
    }
}

